function renderImportQR(){renderImport();app.insertAdjacentHTML('beforeend',`<div class="qr-shade"><div class="qr-panel"><div class="qr-markers"><i></i><i></i><i></i></div><p>Uploading &amp; validating QR<br>code</p></div></div>`);window.clearTimeout(window.flowTimer);window.flowTimer=window.setTimeout(()=>{if(state.screen==='import-qr'){state.screen='story-loading';state.loadingStep=0;render()}},2600);}
function renderStoryLoading(){window.clearInterval(window.heroTimer);window.clearInterval(window.portfolioTimer);window.clearTimeout(window.flowTimer);const labels=['Reading your portfolio','Scanning concentration risk','Mapping your allocations','Reading your holdings','Decoding your investor behaviour','Finding hidden insights','Your deep analysis is ready'];app.innerHTML=`<div class="story-screen story-loading"><div class="story-top">${icon('menu','menu')}<span>Souvik</span><small>◌ Ask AI</small></div><div class="loading-center"><div class="loading-star">${star}</div><p>${labels[Math.min(state.loadingStep,labels.length-1)]}</p></div><div class="loading-glow"></div></div>`;if(state.loadingStep<labels.length-1)window.flowTimer=window.setTimeout(()=>{if(state.screen==='story-loading'){state.loadingStep++;render()}},2800);else window.flowTimer=window.setTimeout(()=>{if(state.screen==='story-loading'){state.screen='story-ready';render()}},2800);}
function renderStoryReady(){window.clearTimeout(window.flowTimer);app.innerHTML=`<div class="story-screen story-ready"><div class="story-top">${icon('menu','menu')}<span>Souvik</span><small>◌ Ask AI</small></div><main class="story-body"><h1>Your story is ready</h1><div class="story-eyebrow">WHAT YOU'LL GET</div><div class="story-benefits"><p><b>Your Past:</b> The decisions and moments that shaped your investing style.</p><p><b>Your Present:</b> A health check on what you own — concentration, overlaps, drag.</p><p><b>Your Future:</b> Prioritised moves tailored to your portfolio and goals.</p></div><div class="story-meta">9 CHAPTERS <span>~7 MIN</span></div><button class="story-button" data-action="story-begin">Begin Reading →</button></main>${nav('portfolio')}</div>`;}
function renderStoryChapter(){const i=state.storyIndex,c=storyChapters[i];app.innerHTML=`<div class="story-screen story-chapter"><div class="story-top">${icon('menu','menu')}<span>Souvik</span><small>◌ Ask AI</small></div><main class="story-body story-reading" id="scrollRoot"><div class="story-eyebrow">CHAPTER ${i+1}</div><h1>${c[0]}</h1><p class="story-lede">${c[1]}</p><div class="story-insight"><p>${c[2]}</p>${i===4?'<div class="health-score">68%</div>':''}${i===5?'<div class="story-donut"></div>':''}${i===8?'<ol><li>Route new SIP money away from Nippon India.</li><li>Add a debt or short-duration fund for the first time.</li><li>Review the two commodity funds together.</li></ol>':''}</div><div class="story-next"><small>${i===8?'YOUR FUTURE':'COMING NEXT'}</small><b>${i===8?'Your story is complete':storyChapters[i+1][0]}</b><button class="story-button" data-action="story-next">${i===8?'Back to portfolio':'Continue →'}</button></div></main>${nav('portfolio')}</div>`;}
