function modal(){const m=state.modal;let content='';if(m==='core')content=`<h2>Want to learn more about<br><b>Core Fund</b></h2><p style="margin-top:28px;font-size:9px">HERE IS HOW WE'LL MOVE FORWARD</p><div class="step"><div class="step-icon">☎</div><div><b>We'll reach out to you in 24 hrs</b><p>Our investment expert will explain the product in detail and help you make the transaction if you're interested in investing.</p></div></div><div class="step"><div class="step-icon">▣</div><div><b>Track your investment on the Ionic app</b><p>Monitor your portfolio performance and stay updated on fund activity.</p></div></div><div class="sheet-actions"><button class="btn ghost" data-action="close-modal">Not Now</button><button class="btn" data-action="interested">I'm Interested</button></div><p class="caption">Your interest is not a commitment.<br>We're here to help you at every step of the way.</p>`;
 else if(m==='account')content=`<h2>Let's setup your account</h2><p>We're excited to help you start! Here's what we'll need:</p><div class="step"><div class="step-icon">◎</div><div><b>Personal Information</b><p>Verify your identity with basic details.</p></div></div><div class="step"><div class="step-icon">♧</div><div><b>Nominee Details</b><p>Add a nominee to protect your investments.</p></div></div><div class="step"><div class="step-icon">▥</div><div><b>Bank Details</b><p>Link your account for easy and secure transactions.</p></div></div><button class="btn full" data-action="close-modal">Proceed to Next Steps</button>`;
 else if(m==='vested')content=`<h2>Powered by ▣ Vested</h2><p>The U.S. Stocks section is powered by Vested. Any U.S. stock investments you make will be through your Vested account and will be governed by Vested's terms and policies.</p><p>By continuing, you acknowledge that you are entering Vested-powered services.</p><u class="small">Read Disclaimer</u><button class="navy-cta" style="margin-top:25px" data-action="close-modal">Continue to US Stocks</button><button class="btn ghost full" style="margin-top:10px" data-action="close-modal">Not now</button>`;
 else if(m==='import')content=`<div style="background:#101018;color:white;margin:-20px -14px 16px;padding:20px 14px 30px"><h2>Import external portfolio<br><span style="color:#999">to see complete analysis.</span></h2><p>Your Past: The decisions and moments that shaped your investing style.</p><p>Your Present: A health check on what you own — concentration, overlaps, drag.</p><p>Your Future: Prioritised moves tailored to your portfolio and goals.</p><button class="btn blue-selected">Import Portfolio →</button></div>`;
 else if(m==='search')content=`<h2>Search</h2><input class="search-box" placeholder="Search offerings" value="${state.search.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}" data-search-input><div class="simple-list">${['Core Fund','Navi Multi Asset Omni FOF','All Weather','BlackRock Smart Beta','Ionic Edge','RedHex Hybrid Long-Short Fund','TRUSTMF Small Cap Fund'].filter(x=>x.toLowerCase().includes(state.search.toLowerCase())).map((x,i)=>`<div class="list-row" data-open="${{'Core Fund':'core','Navi Multi Asset Omni FOF':'nfo','All Weather':'all-weather','BlackRock Smart Beta':'blackrock','Ionic Edge':'edge','RedHex Hybrid Long-Short Fund':'sif','TRUSTMF Small Cap Fund':'mutual'}[x]}">${x}</div>`).join('')}</div>`;
 else if(m==='added-fund')content=`<h2>Added to Cart</h2><p>The fund has been added to your cart.</p><button class="btn full" data-action="cart">View Cart</button><button class="btn ghost full" style="margin-top:8px" data-action="close-modal">Continue exploring</button>`;
 else if(m==='unseen')content=`<h2>${state.unseenName}</h2><p>The provided recording does not show this destination screen. Please share a recording of this flow to make the replica accurate.</p><button class="btn full" data-action="close-modal">Back to offerings</button>`;
 else content=`<h2>${m==='cart'?'Your cart':'Ionic Wealth'}</h2><p>${m==='cart'?'TRUSTMF Small Cap Fund Regular-Growth can be added to your cart.':'Our team will help you with the next step.'}</p><button class="btn full" data-action="close-modal">Close</button>`;
 return `<div class="overlay" data-action="close-modal"><div class="sheet" data-action="noop"><div class="sheet-handle"></div>${content}</div></div>`;}

function renderImport(){window.clearInterval(window.portfolioTimer);window.clearInterval(window.heroTimer);app.innerHTML=`<div class="import-screen"><div class="import-head">${icon('menu','menu')}<span>Souvik</span></div><div class="import-copy"><h1>Import external portfolio<br><span>to see complete analysis.</span></h1><div class="import-benefits"><p><b>Your Past:</b> The decisions and moments that shaped your investing style.</p><p><b>Your Present:</b> A health check on what you own — concentration, overlaps, drag.</p><p><b>Your Future:</b> Prioritised moves tailored to your portfolio and goals.</p></div><button class="import-action" data-action="import-next">Import Portfolio →</button></div></div>${nav('portfolio')}${state.modal?modal():''}`;}
function render(){if(state.screen==='home')renderHome();else if(state.screen==='import')renderImport();else if(state.screen==='import-qr')renderImportQR();else if(state.screen==='story-loading')renderStoryLoading();else if(state.screen==='story-ready')renderStoryReady();else if(state.screen==='story-chapter')renderStoryChapter();else if(state.screen==='fund-list')renderFundList();else if(state.screen==='cart-screen')state.cartItems.length?renderCartWithItems():renderCart();else renderDetail();if(['story-loading','story-ready','story-chapter'].includes(state.screen)&&state.modal)app.insertAdjacentHTML('beforeend',modal());}
function rerenderKeepScroll(){const el=document.getElementById('scrollRoot');const y=el?el.scrollTop:0;render();const next=document.getElementById('scrollRoot');if(next)next.scrollTop=y;}
function openDetail(name){const unseen={'yield':'Yield Enhancer','growth-fund':'Green Lantern Growth Fund','allocate-equity':'Allocate Equity','allocate-moderate':'Allocate Moderate','allocate-aggressive':'Allocate Aggressive','capital-compound':'Capital Compound','commodity':'The Commodity & Energy','icici-mutual':'ICICI Prudential Silver ETF FoF-Growth','union-mutual':'Union Small Cap Fund Regular-Growth','mutual-all':'All Mutual Funds','recommended-funds':'All Recommended Funds','india-aif':'India Multimanager Equity Fund','aif':'Global Asset Allocation','emerging-aif':'Global Emerging Markets (ex-India) Fund'};if(unseen[name]){state.unseenName=unseen[name];state.modal='unseen';rerenderKeepScroll();return}state.screen=name;state.expanded={};state.modal='';state.detailTab='';render();document.getElementById('scrollRoot').scrollTop=0;}
app.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open){openDetail(open.dataset.open);return}const pm=e.target.closest('[data-portfolio-mode]');if(pm){state.portfolioMode=pm.dataset.portfolioMode;state.portfolioSlide=0;rerenderKeepScroll();return}const ps=e.target.closest('[data-portfolio-slide]');if(ps){state.portfolioSlide=Number(ps.dataset.portfolioSlide);rerenderKeepScroll();return}const fee=e.target.closest('[data-fee-tab]');if(fee){state.feeTab=fee.dataset.feeTab;rerenderKeepScroll();return}const global=e.target.closest('[data-global-tab]');if(global){state.globalTab=global.dataset.globalTab;rerenderKeepScroll();return}const mt=e.target.closest('[data-mutual-tab]');if(mt){state.mutualTab=mt.dataset.mutualTab;rerenderKeepScroll();return}const explore=e.target.closest('[data-explore]');if(explore){state.explore=explore.dataset.explore;rerenderKeepScroll();return}const toggle=e.target.closest('[data-toggle]');if(toggle){state.expanded[toggle.dataset.toggle]=!state.expanded[toggle.dataset.toggle];rerenderKeepScroll();return}const action=e.target.closest('[data-action]');if(!action)return;switch(action.dataset.action){case 'noop':break;case 'portfolio':state.screen='home';state.homeTab='portfolio';render();break;case 'exclusives':state.screen='home';state.homeTab='exclusives';render();break;case 'back':state.screen='home';state.modal='';state.homeTab='exclusives';render();break;case 'cta':state.modal=state.screen==='core'?'core':['all-weather','blackrock'].includes(state.screen)?'vested':state.screen==='aif'?'schedule':state.screen==='nfo'?'interest':'account';rerenderKeepScroll();break;case 'close-modal':state.modal='';rerenderKeepScroll();break;case 'interested':state.modal='interest';rerenderKeepScroll();break;case 'import':state.screen='import';state.modal='';render();break;case 'import-next':state.unseenName='Import Portfolio';state.modal='unseen';render();break;case 'search':state.modal='search';rerenderKeepScroll();break;case 'cart':state.modal='cart';rerenderKeepScroll();break;case 'menu':state.modal='menu';rerenderKeepScroll();break;case 'share':if(navigator.share)navigator.share({title:'Ionic Wealth',url:location.href}).catch(()=>{});else {state.modal='share';rerenderKeepScroll()}break;case 'schedule':state.modal='schedule';rerenderKeepScroll();break;case 'global-explore':state.modal='vested';rerenderKeepScroll();break;case 'view-all-pms':state.unseenName='All PMS offerings';state.modal='unseen';rerenderKeepScroll();break;}});
app.addEventListener('input',e=>{if(e.target.matches('[data-search-input]')){state.search=e.target.value;const focus=e.target.selectionStart;rerenderKeepScroll();const next=document.querySelector('[data-search-input]');next?.focus();next?.setSelectionRange(focus,focus);}});
app.addEventListener('click',e=>{const dot=e.target.closest('[data-hero-index]');if(!dot)return;state.hero=Number(dot.dataset.heroIndex);const wrap=document.querySelector('.hero-wrap');if(wrap)wrap.innerHTML=heroSlide(state.hero);});
app.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open&&['mutual-all','recommended-funds'].includes(open.dataset.open)){e.stopImmediatePropagation();state.screen='fund-list';state.mfListTab=open.dataset.open==='mutual-all'?'All MF':'Ionic Recommended';state.mfQuery='';render();return}const tab=e.target.closest('[data-mf-list-tab]');if(tab){e.stopImmediatePropagation();state.mfListTab=tab.dataset.mfListTab;state.mfQuery='';render();return}const action=e.target.closest('[data-action]');if(!action)return;const key=action.dataset.action;if(key==='cart'){e.stopImmediatePropagation();state.returnScreen=state.screen;state.screen='cart-screen';state.modal='';render();return}if(key==='back'&&['fund-list','cart-screen'].includes(state.screen)){e.stopImmediatePropagation();state.screen=state.screen==='cart-screen'?(state.returnScreen||'home'):'home';state.homeTab='exclusives';render();return}if(key==='explore-funds'){e.stopImmediatePropagation();state.screen='fund-list';state.mfListTab='All MF';render();return}if(key==='fund-invest'){e.stopImmediatePropagation();state.modal='account';rerenderKeepScroll();return}if(key==='add-fund'){e.stopImmediatePropagation();state.cartItems.push(action.dataset.fund);state.modal='added-fund';rerenderKeepScroll();return}},true);
app.addEventListener('input',e=>{if(!e.target.matches('[data-mf-search]'))return;state.mfQuery=e.target.value;const focus=e.target.selectionStart;renderFundList();const next=document.querySelector('[data-mf-search]');next?.focus();next?.setSelectionRange(focus,focus);});
function menuMarkup(){return `<div class="menu-overlay" data-action="close-modal"><aside class="menu-drawer" data-action="noop"><div class="menu-blue"></div><div class="menu-avatar">S</div><div class="menu-user"><b>Souvik</b><span>demo@example.com</span><span>Demo account</span></div><div class="menu-line"><span>Risk Profile</span><button data-action="risk-profile">Start ›</button></div><div class="menu-line"><span>App Lock</span><button class="lock-switch" data-action="toggle-lock" aria-label="Toggle app lock"><i></i></button></div><div class="menu-manager"><small>Your relationship manager</small><span>Relationship manager</span><span>Ionic relationship manager</span></div><button class="menu-signout" data-action="signout">Sign out</button><div class="menu-legal">Privacy policy ・ Terms of service<p>AMFI Registered Mutual Fund Distributor<br>Angel One Investment Services Private Limited (AOISPL)<br>ARN AOISPL – 306165</p><button data-action="delete-account">Delete Account</button></div></aside></div>`;}
const ordinaryModal=modal;modal=function(){return state.modal==='menu'?menuMarkup():ordinaryModal();};
app.addEventListener('click',e=>{const remove=e.target.closest('[data-remove-fund]');if(remove){e.stopImmediatePropagation();state.cartItems=state.cartItems.filter(x=>x!==remove.dataset.removeFund);render();return}const action=e.target.closest('[data-action]');if(action&&['risk-profile','signout','delete-account'].includes(action.dataset.action)){e.stopImmediatePropagation();state.unseenName=action.textContent.trim();state.modal='unseen';rerenderKeepScroll();return}if(action?.dataset.action==='toggle-lock'){e.stopImmediatePropagation();action.classList.toggle('on');return}},true);
app.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(!open)return;const names={'sif-all':'All Specialized Investment Funds','sif-sapphire':'Sapphire Equity Long-Short Fund','sif-altiva':'Altiva Hybrid Long-Short Fund','sif-titanium':'Titanium Hybrid Long Short Fund','sif-isif':'iSIF Equity Ex Top 100 Long-Short Fund','sif-arudha':'Arudha Hybrid Long-Short Fund','nippon-mutual':'Nippon India Taiwan Equity Fund','mirae-fang':'Mirae Asset NYSE FANG+ ETF FoF','mirae-sp500':'Mirae Asset S&P 500 Top 50 ETF'};if(!names[open.dataset.open])return;e.stopImmediatePropagation();state.unseenName=names[open.dataset.open];state.modal='unseen';rerenderKeepScroll();},true);
app.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(!action)return;const key=action.dataset.action;if(key==='import-next'){e.stopImmediatePropagation();state.screen='import-qr';state.modal='';render();return}if(key==='story-begin'){e.stopImmediatePropagation();state.storyIndex=0;state.screen='story-chapter';render();return}if(key==='story-next'){e.stopImmediatePropagation();if(state.storyIndex<storyChapters.length-1){state.storyIndex++;render();document.getElementById('scrollRoot').scrollTop=0}else{state.screen='home';state.homeTab='portfolio';render()}return}},true);
render();






